// Canonical Decimal arithmetic. Browser copy is generated by scripts/sync-financial.mjs.
// Numbers are compatibility/display boundaries; all monetary arithmetic uses Decimal.
import DecimalModule from 'decimal.js-light';
import type { Decimal as DecimalType } from 'decimal.js-light';
// Native Node ESM imports the CommonJS constructor through default. The named
// export works in Vite/Vitest but is not provided by Node's CJS export detection.
const DecimalConstructor = DecimalModule as unknown as typeof DecimalType;
export const Decimal = DecimalConstructor.clone({ precision: 80, rounding: DecimalConstructor.ROUND_HALF_UP });
export type DecimalValue = InstanceType<typeof Decimal>;
// Decimal strings are the wire format; numbers remain accepted for older callers.
export type MoneyValue = string | number;
const MAX_CENTS = new Decimal(Number.MAX_SAFE_INTEGER);
export const MAX_STORED_CENTS = 999999999999; // PostgreSQL Decimal(12,2)
export const financialError = (message: string) => Object.assign(new Error(message), { status: 400 });
export function assertNoTax(value: unknown) {
  if (value === undefined || value === null) return;
  if (!decimal(value).isZero()) {
    throw financialError('Tax is not supported');
  }
}
export function assertNoTaxPayload(payload: unknown) {
  if (!payload || typeof payload !== 'object') return;
  if (Array.isArray(payload)) {
    payload.forEach(assertNoTaxPayload);
    return;
  }
  for (const [key, value] of Object.entries(payload)) {
    const normalizedKey = key.toLowerCase().replace(/[^a-z]/g, '');
    if (normalizedKey.includes('tax') || normalizedKey.includes('vat')) assertNoTax(value);
    else assertNoTaxPayload(value);
  }
}
export function decimal(value: unknown = 0): DecimalValue {
  let text = String(value ?? 0).trim().replace(/[\s\u00a0\u202f]/g, '');
  if (text.includes(',') && text.includes('.')) {
    const separator = text.lastIndexOf(',') > text.lastIndexOf('.') ? ',' : '.';
    text = text.split(separator === ',' ? '.' : ',').join('').replace(separator, '.');
  } else text = text.replace(',', '.');
  text = text.replace(/^([+-]?)\./, (_match, sign) => `${sign}0.`);
  const match = /^([+-]?)(\d+)(?:\.(\d*))?(?:e([+-]?\d+))?$/i.exec(text);
  if (!match) throw financialError('Invalid finite monetary value');
  const exponent = Number(match[4] || 0) - (match[3]?.length || 0);
  if (Math.abs(exponent) > 30 || (match[2] + (match[3] || '')).length > 60) throw financialError('Monetary precision out of range');
  return new Decimal(text);
}
// Decimal values cross JSON as decimal strings. Counts, quantities, IDs and
// chart geometry remain numbers; spelling is shared by browser and server.
const financialKeys = new Set([
  'amount', 'paid', 'debt', 'balance', 'price', 'cost', 'profit', 'revenue',
  'sellingprice', 'costprice', 'purchasecostprice', 'packagesellingprice',
  'costpriceperbaseunit', 'effectivecostpriceperbaseunit', 'costattime', 'sellingattime',
  'discount', 'itemdiscount', 'expensepercent', 'allocatedorderdiscount', 'eligiblenetamount',
  'totalamount', 'netamount', 'paidamount', 'returnedamount', 'originalamount',
  'originalnetamount', 'originalpaidamount', 'totalprice', 'totalvalue', 'totalcost',
  'refundamount', 'refundedamount', 'cashrefundamount', 'debtreduction', 'creditamount',
  'totalinvoiced', 'totalpaid', 'totaldebt', 'purchasedtotal', 'paidtotal', 'debttotal',
  'grosspaidamount', 'moneyrefundedamount', 'balancepaidamount', 'invoicebalance',
  'salebasisamount', 'currentnetamount', 'debtamount', 'originalvalue', 'returnedvalue',
  'totalsales', 'netsales', 'grosssales', 'costtotal', 'totalrevenue', 'totalprofit',
  'totalexpenses', 'totaldebts', 'stockvaluation', 'inventoryvalue', 'salesbeforereturns',
  'currentnet', 'grosscollections', 'netcollections', 'moneyrefunded', 'paymentreversals',
  'returnpaymentadjustments', 'outstandingdebt', 'averagecheck', 'averagerevenue',
]);
export function financialJsonReplacer(key: string, value: unknown): unknown {
  const normalized = key.toLowerCase().replace(/_/g, '');
  if (financialKeys.has(normalized) && value !== null && value !== undefined && value !== '' &&
      (typeof value === 'number' || typeof value === 'string')) return decimal(value).toString();
  return value;
}
export function financialPayload<T>(value: T): T {
  // JSON is the explicit transport boundary; Decimal.toJSON is a decimal string.
  return JSON.parse(JSON.stringify(value, financialJsonReplacer));
}
export function toCents(value: unknown): number {
  const cents = decimal(value).times(100).toDecimalPlaces(0, Decimal.ROUND_HALF_UP);
  if (cents.abs().gt(MAX_CENTS)) throw financialError('Monetary amount out of range');
  return cents.toNumber();
}
export const fromCents = (cents: number) => {
  if (!Number.isSafeInteger(cents)) throw financialError('Invalid minor units');
  return new Decimal(cents).div(100).toNumber();
};
export const addMoney = (...values: unknown[]) => {
  const cents = values.reduce<DecimalValue>((sum, value) => sum.plus(toCents(value)), new Decimal(0));
  if (cents.abs().gt(MAX_CENTS)) throw financialError('Monetary amount out of range');
  return cents.div(100).toNumber();
};
export function quantity(value: unknown, allowZero = false): number {
  const n = Number(value);
  if (!Number.isSafeInteger(n) || n < 0 || (!allowZero && n === 0)) throw financialError('Quantity must be a positive whole number');
  return n;
}
export function percent(value: unknown): number {
  return decimal(percentText(value)).toNumber();
}
export function percentText(value: unknown): string {
  const n = decimal(value ?? 0);
  if (n.lt(0) || n.gt(100)) throw financialError('Discount must be between 0 and 100%');
  return n.toString();
}
export function discountedUnit(price: unknown, discount: unknown = 0): number {
  const cents = new Decimal(toCents(price));
  if (cents.lt(0)) throw financialError('Price must be non-negative');
  percent(discount);
  return fromCents(cents.times(new Decimal(100).minus(decimal(discount))).div(100).toDecimalPlaces(0, Decimal.ROUND_CEIL).toNumber());
}
export function lineTotal(qty: unknown, price: unknown, discount: unknown = 0): number {
  return fromCents(new Decimal(quantity(qty, true)).times(toCents(discountedUnit(price, discount))).toNumber());
}
export function discountAmount(total: unknown, discount: unknown = 0): number {
  percent(discount);
  return fromCents(new Decimal(toCents(total)).times(decimal(discount)).div(100).toDecimalPlaces(0, Decimal.ROUND_HALF_UP).toNumber());
}
// Largest remainders conserve cents exactly; stable input order breaks ties.
export function allocateCents(amount: number, weights: number[]): number[] {
  if (!Number.isSafeInteger(amount) || amount < 0 || weights.some(w => !Number.isSafeInteger(w) || w < 0)) throw financialError('Invalid allocation');
  const total = weights.reduce((sum, w) => sum.plus(w), new Decimal(0));
  if (total.isZero()) { if (amount !== 0) throw financialError('Cannot allocate a nonzero amount to zero weights'); return weights.map(() => 0); }
  const rows = weights.map((w, index) => {
    const product = new Decimal(amount).times(w);
    return { index, value: product.idiv(total).toNumber(), remainder: product.mod(total) };
  });
  let left = new Decimal(amount).minus(rows.reduce((sum, r) => sum.plus(r.value), new Decimal(0))).toNumber();
  for (const row of [...rows].sort((a, b) => b.remainder.cmp(a.remainder) || a.index - b.index)) { if (left-- <= 0) break; row.value++; }
  return rows.map(r => r.value);
}
export function cumulativeValue(total: unknown, returned: unknown, sold: unknown): number {
  const count = quantity(sold); const used = quantity(returned, true);
  if (used > count) throw financialError('Returned quantity exceeds original quantity');
  return fromCents(new Decimal(toCents(total)).times(used).div(count).toDecimalPlaces(0, Decimal.ROUND_HALF_UP).toNumber());
}
export function saleTotals(items: any[], orderDiscount: unknown = 0) {
  const totals = items.map(i => lineTotal(i.totalBaseUnits ?? i.quantity, i.sellingPrice, i.discount ?? 0));
  const subtotal = addMoney(...totals); const discount = discountAmount(subtotal, orderDiscount);
  const allocations = allocateCents(toCents(discount), totals.map(toCents));
  if ([subtotal, addMoney(subtotal, -discount)].some(value => toCents(value) > MAX_STORED_CENTS)) throw financialError('Invoice amount exceeds database monetary range');
  return { subtotal, discount, net: addMoney(subtotal, -discount), lines: totals.map((total, i) => ({ total, orderDiscount: fromCents(allocations[i]), eligibleNet: addMoney(total, -fromCents(allocations[i])) })) };
}
export function invoiceLines(invoice: any) {
  const items: any[] = invoice.items || [];
  const totals = items.map(i => i.totalPrice != null ? toCents(i.totalPrice) : toCents(lineTotal(i.quantity, i.sellingPrice, i.discount ?? 0)));
  const allocations = allocateCents(toCents(discountAmount(fromCents(totals.reduce((s, n) => s.plus(n), new Decimal(0)).toNumber()), invoice.discount ?? 0)), totals);
  return items.map((item, index) => {
    const eligible = item.eligibleNetAmount != null ? Number(item.eligibleNetAmount) : fromCents(new Decimal(totals[index]).minus(allocations[index]).toNumber());
    const returned = cumulativeValue(eligible, item.returnedQty || 0, item.quantity);
    return { ...item, originalLineTotal: fromCents(totals[index]), allocatedOrderDiscount: item.allocatedOrderDiscount != null ? Number(item.allocatedOrderDiscount) : fromCents(allocations[index]), eligibleNetAmount: eligible,
      returnedNetAmount: returned, remainingNetAmount: addMoney(eligible, -returned), remainingQuantity: quantity(item.quantity) - quantity(item.returnedQty || 0, true) };
  });
}
export function refundByMethod(payments: any[], refund: unknown) {
  const methods = ['cash', 'card', 'transfer'];
  const buckets = methods.map(method => toCents(addMoney(...payments.filter(p => p.method === method).map(p => p.amount))));
  if (buckets.some(n => n < 0) || payments.some(p => !methods.includes(p.method) && toCents(p.amount) !== 0)) throw financialError('Historical refund payment methods require reconciliation');
  const cents = toCents(refund);
  if (cents > buckets.reduce((s, n) => s.plus(n), new Decimal(0)).toNumber()) throw financialError('Refund exceeds available payments');
  return allocateCents(cents, buckets).map((amount, i) => ({ method: methods[i], amount: fromCents(amount) })).filter(p => p.amount > 0);
}
export function isGoodsReturnPaymentAdjustment(payment: any) {
  return toCents(payment?.amount ?? 0) < 0 && !payment?.reversalOfId &&
    (payment?.returnId != null || String(payment?.method || '').toLowerCase() === 'refund');
}
export function goodsReturnPaymentAdjustments(payments: any[]) {
  return fromCents(payments.filter(isGoodsReturnPaymentAdjustment).reduce((sum: DecimalValue, payment: any) => sum.minus(toCents(payment.amount)), new Decimal(0)).toNumber());
}
export function balancePaidAmount(payments: any[], fallback: unknown = 0) {
  if (!Array.isArray(payments)) return fromCents(toCents(fallback));
  return addMoney(...payments.filter((payment: any) => !isGoodsReturnPaymentAdjustment(payment)).map((payment: any) => payment.amount));
}
export function refundSplit(net: unknown, paid: unknown, eligible: unknown) {
  const n = toCents(net), p = toCents(paid), r = toCents(eligible);
  if (n < 0 || p < 0 || r < 0 || r > n) throw financialError('Financial reconciliation required before return');
  const debtReduction = Math.min(Math.max(0, new Decimal(n).minus(p).toNumber()), r);
  const netAmount = new Decimal(n).minus(r).toNumber();
  return {
    refundedAmount: 0,
    debtReduction: fromCents(debtReduction),
    creditAmount: 0,
    netAmount: fromCents(netAmount),
    paidAmount: fromCents(p),
    debtAmount: fromCents(Math.max(0, new Decimal(netAmount).minus(p).toNumber())),
  };
}
